css:
.datasense-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e0e6f0;
    line-height: 1.5;
}

.datasense-sim-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 24px;
    border-left: 4px solid #00ff88;
    padding: 22px 28px;
    margin-bottom: 28px;
    background: linear-gradient(90deg, rgba(0,255,136,0.06), rgba(0,191,255,0.02));
    border-radius: 0 8px 8px 0;
}
.datasense-sim-header-left { flex: 1; }
.datasense-sim-eyebrow {
    color: #6b7280;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 8px;
}
.datasense-sim-header h1 {
    color: #00ff88;
    font-size: 1.55rem;
    letter-spacing: 0.04em;
    margin: 0 0 6px 0;
    font-weight: 600;
}
.datasense-sim-subtitle {
    color: #9aa3b2;
    font-size: 0.95rem;
}
.datasense-sim-period-pill {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: #111827;
    border: 1px solid #1f2d3d;
    color: #00bfff;
    padding: 8px 16px;
    border-radius: 999px;
    font-size: 0.85rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    font-weight: 600;
}
.datasense-sim-period-pill span:nth-child(2) {
    color: #00ff88;
    font-weight: 700;
    font-size: 1rem;
}

.datasense-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}
.datasense-sim-status-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 10px;
    padding: 18px 18px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.2s ease;
}
.datasense-sim-status-card:hover {
    border-color: #00ff88;
    transform: translateY(-2px);
}
.datasense-sim-status-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00ff88, #00bfff);
}
.datasense-sim-label {
    color: #6b7280;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 10px;
    font-weight: 600;
}
.datasense-sim-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #e0e6f0;
    line-height: 1.1;
}
.datasense-sim-value-primary { color: #00ff88; }
.datasense-sim-value-text {
    font-size: 0.95rem;
    font-weight: 500;
    color: #00bfff;
    line-height: 1.3;
}

.datasense-sim-main {
    display: grid;
    grid-template-columns: 1.05fr 1fr;
    gap: 20px;
    margin-bottom: 28px;
}
@media (max-width: 980px) {
    .datasense-sim-main { grid-template-columns: 1fr; }
}

.datasense-sim-briefing {
    background: #0f172a;
    border: 1px solid #1f2d3d;
    border-radius: 10px;
    padding: 22px 22px 18px;
    position: relative;
    overflow: hidden;
}
.datasense-sim-briefing::before {
    content: '';
    position: absolute;
    top: 0; left: 0; bottom: 0;
    width: 3px;
    background: linear-gradient(180deg, #ff6b35, #ffb000);
}
.datasense-sim-briefing-header {
    display: flex;
    align-items: baseline;
    gap: 14px;
    border-bottom: 1px dashed #1f2d3d;
    padding-bottom: 12px;
    margin-bottom: 14px;
}
.datasense-sim-briefing-time {
    color: #ff6b35;
    font-size: 0.75rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    font-weight: 700;
    background: rgba(255,107,53,0.1);
    padding: 4px 10px;
    border-radius: 4px;
}
.datasense-sim-briefing-title {
    color: #e0e6f0;
    font-size: 1.15rem;
    font-weight: 600;
    flex: 1;
}
.datasense-sim-briefing-body {
    color: #c5cdd9;
    font-size: 0.95rem;
    margin-bottom: 14px;
}
.datasense-sim-artifact-goal {
    background: rgba(0,191,255,0.06);
    border: 1px solid rgba(0,191,255,0.2);
    border-radius: 6px;
    padding: 10px 14px;
    font-size: 0.88rem;
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.datasense-sim-artifact-goal-label {
    color: #00bfff;
    font-size: 0.7rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    font-weight: 700;
}
.datasense-sim-artifact-goal-text {
    color: #e0e6f0;
}

.datasense-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 10px;
    padding: 22px;
}
.datasense-sim-controls h3 {
    color: #00ff88;
    font-size: 0.78rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    margin: 0 0 16px 0;
    font-weight: 700;
}
.datasense-sim-decision {
    margin-bottom: 14px;
}
.datasense-sim-dec-label {
    display: block;
    color: #c5cdd9;
    font-size: 0.85rem;
    font-weight: 500;
    margin-bottom: 6px;
}
.datasense-sim-select {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 6px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.9rem;
    transition: border-color 0.2s ease;
}
.datasense-sim-select:focus {
    outline: none;
    border-color: #00ff88;
    box-shadow: 0 0 0 2px rgba(0,255,136,0.15);
}
.datasense-sim-select option {
    background: #111827;
    color: #e0e6f0;
}
.datasense-sim-controls input[type="text"],
.datasense-sim-controls input[type="number"] {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 6px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.9rem;
}

.datasense-sim-controls-actions {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top: 18px;
    padding-top: 16px;
    border-top: 1px dashed #1f2d3d;
}
.datasense-sim-btn-primary {
    background: linear-gradient(135deg, #00ff88, #00bfff);
    border: none;
    color: #0a0f1e;
    font-weight: 700;
    padding: 11px 22px;
    border-radius: 6px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    font-size: 0.82rem;
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}
.datasense-sim-btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 18px rgba(0,255,136,0.25);
    color: #0a0f1e;
}
.datasense-sim-btn-undo {
    background: transparent;
    border: 1px solid #2d3f55;
    color: #9aa3b2;
    padding: 9px 16px;
    font-size: 0.78rem;
    border-radius: 6px;
}
.datasense-sim-btn-undo:hover {
    color: #e0e6f0;
    border-color: #00bfff;
    background: rgba(0,191,255,0.05);
}

.datasense-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 10px;
    padding: 22px;
    margin-bottom: 24px;
}
.datasense-sim-history h3 {
    color: #00bfff;
    font-size: 0.78rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    margin: 0 0 14px 0;
    font-weight: 700;
}
.datasense-sim-table {
    color: #c5cdd9;
    margin: 0;
    font-size: 0.88rem;
}
.datasense-sim-table thead th {
    color: #6b7280;
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    border-bottom: 1px solid #2d3f55;
    border-top: none;
    background: transparent;
    font-weight: 600;
    padding: 10px 12px;
}
.datasense-sim-table tbody td {
    border-top: 1px solid #1f2d3d;
    padding: 10px 12px;
    color: #c5cdd9;
}
.datasense-sim-table tbody tr:hover {
    background: rgba(0,191,255,0.04);
}

.datasense-sim-chart {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 10px;
    padding: 22px;
    height: 320px;
}

@media (max-width: 768px) {
    .datasense-sim-container { padding: 14px; }
    .datasense-sim-header { flex-direction: column; padding: 18px 20px; }
    .datasense-sim-header h1 { font-size: 1.25rem; }
    .datasense-sim-status-cards { grid-template-columns: 1fr 1fr; }
    .datasense-sim-value { font-size: 1.4rem; }
    .datasense-sim-controls-actions { flex-direction: column; align-items: stretch; }
    .datasense-sim-chart { height: 260px; }
}


/* FIX v1.1.0 - completion / decision-debrief screen */
.datasense-sim-completion { padding: 8px 4px; text-align: center; }
.datasense-sim-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.datasense-sim-completion-verdict { font-size: 24px; font-weight: 700; color: #0f172a; margin-bottom: 14px; }
.datasense-sim-completion-score { display: inline-flex; align-items: baseline; gap: 8px; padding: 8px 16px; background: #f1f5f9; border-radius: 8px; margin-bottom: 18px; }
.datasense-sim-completion-score span { font-size: 13px; color: #64748b; }
.datasense-sim-completion-score strong { font-size: 20px; color: #0f172a; }
.datasense-sim-completion-insights-heading { font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: #64748b; margin-bottom: 8px; }
.datasense-sim-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 640px; text-align: left; }
.datasense-sim-completion-insights li { padding: 10px 14px; margin-bottom: 8px; background: #f8fafc; border-left: 3px solid #0ea5e9; border-radius: 4px; color: #1e293b; font-size: 14px; }

