(function() {
    'use strict';

    var ROUNDS = [
        {
            num: 1,
            decisions: [
                { id: 'reply_cmo',  options: ['a','b','c'],     correct: 'b' },
                { id: 'diego_task', options: ['a','b','c'],     correct: 'b' },
                { id: 'sofia_task', options: ['a','b','c'],     correct: 'c' },
                { id: 'docs_format',options: ['a','b','c'],     correct: 'b' }
            ]
        },
        {
            num: 2,
            decisions: [
                { id: 'charts_kept',     options: ['a','b','c','d'], correct: 'c' },
                { id: 'migration_annot', options: ['a','b','c'],     correct: 'b' },
                { id: 'note_format',     options: ['a','b','c'],     correct: 'b' },
                { id: 'hernan_signoff',  options: ['a','b','c'],     correct: 'c' }
            ]
        },
        {
            num: 3,
            decisions: [
                { id: 'number_one',     options: ['a','b','c'], correct: 'b' },
                { id: 'number_two',     options: ['a','b','c'], correct: 'b' },
                { id: 'number_three',   options: ['a','b','c'], correct: 'b' },
                { id: 'recommendation', options: ['a','b','c'], correct: 'b' },
                { id: 'named_risk',     options: ['a','b','c'], correct: 'a' }
            ]
        },
        {
            num: 4,
            decisions: [
                { id: 'commitment', options: ['a','b','c','d'], correct: 'any' }
            ]
        }
    ];

    var ROUND_WEIGHTS = [25, 25, 40, 10];

    class DataSenseAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'DataSense — From Dashboards to Decisions';
            this.version = '1.1.0';
            this.ROUNDS = ROUNDS;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    artifactsBuilt: 0,
                    qualityHistory: [],
                    correctnessHistory: [],
                    artifactNames: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._renderRound(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            for (var i = 0; i < round.decisions.length; i++) {
                var d = round.decisions[i];
                var el = document.getElementById('dec_' + d.id);
                if (!el || !el.value) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('all_decisions_warning'), 'warning'
                    );
                    return false;
                }
                decisions[d.id] = el.value;
            }
            return true;
        }

        calculateResults(state) {
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var correct = 0;
            var total = 0;
            for (var i = 0; i < round.decisions.length; i++) {
                var d = round.decisions[i];
                var ans = state.decisions[d.id];
                var isCorrect = (d.correct === 'any') || (ans === d.correct);
                if (isCorrect) correct++;
                total++;
            }
            var quality = total > 0 ? Math.round((correct / total) * 100) : 0;
            var roundWeight = ROUND_WEIGHTS[roundIdx] || 0;
            var weightedScore = Math.round((correct / total) * roundWeight);

            state.domainState.totalScore += weightedScore;

            // FIX v1.1.0 - expose score to the Express reporting layer
            // (express_resolveDomainScore reads performance.overallScore then top-level
            // `score`; original wrote only totalScore, so the panel showed "-").
            // totalScore is 0-100 (sum of per-round correct-ratio * roundWeight).
            state.domainState.score = state.domainState.totalScore;
            state.domainState.performance = { overallScore: state.domainState.totalScore, grade: this._grade(state.domainState.totalScore) };
            state.domainState.artifactsBuilt += 1;
            state.domainState.qualityHistory.push(quality);
            state.domainState.correctnessHistory.push(correct + '/' + total);

            var artifactName = window.mySimulation.t('artifact_r' + round.num);
            state.domainState.artifactNames.push(artifactName);

            var self = this;
            setTimeout(function() {
                self._renderRound({ currentPeriod: state.currentPeriod + 1 });
            }, 600);

            return {
                period: state.currentPeriod,
                round: round.num,
                quality: quality,
                correct: correct,
                total: total,
                correctness: correct + '/' + total,
                weightedScore: weightedScore,
                artifact: artifactName,
                cumulativeScore: state.domainState.totalScore
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore', function(v) {
                return Math.round(v) + '/100';
            });
            uiManager.bind('artifactsBuiltDisplay', 'domainState.artifactsBuilt', function(v) {
                return v + '/4';
            });
            uiManager.bind('lastQualityDisplay', 'results.quality', function(v) {
                return (v == null ? '—' : v + '%');
            });
            uiManager.bind('lastArtifactDisplay', 'results.artifact');
        }

        getChartConfig() {
            return {
                qualityChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Artifact Quality (%)',
                            data: [],
                            backgroundColor: 'rgba(0,255,136,0.18)',
                            borderColor: '#00ff88',
                            borderWidth: 2,
                            borderRadius: 4
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Artifact Quality by Round', color: '#e0e6f0', font: { size: 14, weight: '600' } },
                            legend: { labels: { color: '#9aa3b2' } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100, ticks: { color: '#9aa3b2' }, grid: { color: '#1f2d3d' } },
                            x: { ticks: { color: '#9aa3b2' }, grid: { color: 'transparent' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.qualityHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                qualityChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.qualityHistory }]
                }
            };
        }

        _t() {
            return (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
        }

        _grade(s) {
            if (s >= 80) return 'A';
            if (s >= 60) return 'B';
            if (s >= 40) return 'C';
            return 'D';
        }

        formatCompletionMessage(summary) {
            var t = this._t();
            summary = summary || {};
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore
                      : (typeof summary.totalScore === 'number') ? summary.totalScore : 0;
            var verdict = summary.performance || '';
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="datasense-sim-completion">'
                +   '<div class="datasense-sim-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="datasense-sim-completion-verdict">' + verdict + '</div>'
                +   '<div class="datasense-sim-completion-score"><span>' + t('comp_score_label') + '</span>'
                +     '<strong>' + score + '/100</strong></div>'
                +   '<div class="datasense-sim-completion-insights-heading">' + t('comp_insights_heading') + '</div>'
                +   '<ul class="datasense-sim-completion-insights">' + items + '</ul>'
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = 0;
            var qualities = [];
            for (var i = 0; i < history.length; i++) {
                totalScore += (history[i].results && history[i].results.weightedScore) || 0;
                qualities.push((history[i].results && history[i].results.quality) || 0);
            }
            var avgQuality = qualities.length
                ? qualities.reduce(function(s, q) { return s + q; }, 0) / qualities.length
                : 0;

            var performance, insights;
            if (totalScore >= 80) {
                performance = window.mySimulation.t('perf_excellent');
                insights = [
                    window.mySimulation.t('insight_excellent_1'),
                    window.mySimulation.t('insight_excellent_2')
                ];
            } else if (totalScore >= 60) {
                performance = window.mySimulation.t('perf_proficient');
                insights = [
                    window.mySimulation.t('insight_proficient_1'),
                    window.mySimulation.t('insight_proficient_2')
                ];
            } else if (totalScore >= 40) {
                performance = window.mySimulation.t('perf_developing');
                insights = [
                    window.mySimulation.t('insight_developing_1'),
                    window.mySimulation.t('insight_developing_2')
                ];
            } else {
                performance = window.mySimulation.t('perf_notyet');
                insights = [
                    window.mySimulation.t('insight_notyet_1'),
                    window.mySimulation.t('insight_notyet_2')
                ];
            }

            return {
                totalPeriods: history.length,
                totalScore: totalScore,
                overallScore: totalScore,
                avgQuality: Math.round(avgQuality),
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.quality >= 80) return window.mySimulation.t('hint_strong');
            if (results.quality >= 50) return window.mySimulation.t('hint_mid');
            return window.mySimulation.t('hint_weak');
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.round',         label: 'Round',     i18nKey: 'col_round' },
                { key: 'results.artifact',      label: 'Artifact',  i18nKey: 'col_artifact' },
                { key: 'results.correctness',   label: 'Correct',   i18nKey: 'col_correct' },
                { key: 'results.quality',       label: 'Quality',   i18nKey: 'col_quality',
                  formatter: function(v) { return v + '%'; } },
                { key: 'results.weightedScore', label: 'Score',     i18nKey: 'col_score',
                  formatter: function(v) { return v + ' pts'; } }
            ];
        }

        getPresets() { return null; }

        _renderRound(state) {
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var sim = window.mySimulation;
            var t = (sim && sim.t) ? function(k) { return sim.t(k); } : function(k) { return k; };

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = t('r' + round.num + '_title');

            var timeEl = document.getElementById('roundTime');
            if (timeEl) timeEl.textContent = t('r' + round.num + '_time');

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t('r' + round.num + '_brief');

            var artifactEl = document.getElementById('artifactGoal');
            if (artifactEl) artifactEl.textContent = t('r' + round.num + '_artifact');

            var panel = document.getElementById('decisionsPanel');
            if (!panel) return;

            var html = '';
            for (var i = 0; i < round.decisions.length; i++) {
                var d = round.decisions[i];
                var labelKey = 'r' + round.num + '_' + d.id + '_label';
                html += '<div class="datasense-sim-decision">';
                html += '<label class="datasense-sim-dec-label" for="dec_' + d.id + '">' + t(labelKey) + '</label>';
                html += '<select id="dec_' + d.id + '" class="datasense-sim-select">';
                html += '<option value="">' + t('select_placeholder') + '</option>';
                for (var j = 0; j < d.options.length; j++) {
                    var optKey = 'r' + round.num + '_' + d.id + '_' + d.options[j];
                    html += '<option value="' + d.options[j] + '">' + t(optKey) + '</option>';
                }
                html += '</select>';
                html += '</div>';
            }
            panel.innerHTML = html;
        }

        getTranslations() {
            return {
                en: {
                    title:                    `DataSense — From Dashboards to Decisions`,
                    eyebrow:                  `CARIBIA BANCA DIGITAL · MARKETING OPERATIONS`,
                    subtitle:                 `48 hours. Four artifacts. One defensible read for the board.`,
                    period_label:             `Round`,
                    period_of:                `of`,
                    status_score:             `Cumulative Score`,
                    status_artifacts:         `Artifacts Built`,
                    status_quality:           `Last Artifact Quality`,
                    status_artifact:          `Last Artifact`,
                    decisions_heading:        `Your Decisions`,
                    artifact_goal_heading:    `Deliverable`,
                    history_heading:          `Round Log`,
